mapper.select:
SELECT * FROM search_popular_cache
 WHERE period_type = #{periodType}
   AND period_date = #{periodDate}
   AND locale      = #{locale}
 ORDER BY rank ASC
 LIMIT #{limit}

mapper.delete:
DELETE FROM search_popular_cache
 WHERE period_type = #{periodType}
   AND period_date = #{periodDate}
   AND locale      = #{locale}

mapper.select:
SELECT COUNT(*) FROM search_popular_cache
 WHERE period_type = #{periodType}
   AND period_date = #{periodDate}
   AND locale      = #{locale}
